'use strict';
const PREFIX='orthodox-way-offline-';
self.addEventListener('install',event=>event.waitUntil(self.skipWaiting()));
self.addEventListener('activate',event=>event.waitUntil(self.clients.claim()));
self.addEventListener('message',event=>{const port=event.ports[0];if(!port)return;event.waitUntil((async()=>{try{
  if(event.data.type==='remove'){for(const name of await caches.keys())if(name.startsWith(PREFIX))await caches.delete(name);port.postMessage({ok:true});return;}
  if(event.data.type!=='download')throw new Error('Unknown offline operation.');
  const response=await fetch(new URL('offline-manifest.json',self.registration.scope),{cache:'no-store'});if(!response.ok)throw new Error('Offline catalogue unavailable.');const manifest=await response.json(),pack=manifest.packs.find(p=>p.id===event.data.pack);if(!pack)throw new Error('Unknown reading collection.');
  const cache=await caches.open(PREFIX+manifest.version+'-'+pack.id);let completed=0;const failures=[];
  for(const file of pack.files){const url=new URL(file,self.registration.scope);if(url.origin!==self.location.origin||url.pathname.includes('/api/')||url.pathname.includes('/__'))throw new Error('Invalid offline asset.');try{const asset=await fetch(url,{cache:'reload'});if(!asset.ok)throw new Error('Unavailable file');await cache.put(url,asset);completed++;port.postMessage({type:'progress',completed,total:pack.files.length});}catch{failures.push(file);}}
  if(failures.length)throw new Error('Download incomplete ('+failures.length+' files). Reconnect and download this collection again.');await cache.put(new URL('offline-manifest.json',self.registration.scope),new Response(JSON.stringify(manifest),{headers:{'Content-Type':'application/json'}}));port.postMessage({ok:true,completed});
}catch(error){port.postMessage({ok:false,error:error.message});}})());});
self.addEventListener('fetch',event=>{const request=event.request,url=new URL(request.url);if(request.method!=='GET'||url.origin!==self.location.origin||url.pathname.includes('/api/')||url.pathname.includes('/.netlify/')||url.pathname.includes('/__')||request.headers.has('Authorization'))return;
  event.respondWith((async()=>{try{return await fetch(request);}catch{const names=(await caches.keys()).filter(name=>name.startsWith(PREFIX)).reverse();for(const name of names){const cache=await caches.open(name),cached=await cache.match(request,{ignoreSearch:true});if(cached)return cached;if(url.pathname.endsWith('/')){const page=await cache.match(new URL(url.pathname+'index.html',url.origin),{ignoreSearch:true});if(page)return page;}const scopePath=new URL(self.registration.scope).pathname,isAppPath=url.pathname===scopePath||url.pathname===scopePath+'index.html';if(request.mode==='navigate'&&isAppPath){const index=await cache.match(new URL('index.html',self.registration.scope));if(index)return index;}}return new Response('This reading is not downloaded. Reconnect and choose an offline collection.',{status:503,headers:{'Content-Type':'text/plain'}});}})());});
